// NOTE: the README only documents JxButton, JxModal, JxDrawer, JxTabs, JxSelect,
// JxCombobox, JxCalendar, JxDateRangePicker and the value/onValueChange contract.
// JxCard, JxBadge, JxSlider, JxSwitch, JxDivider, JxTabList/JxTab, JxOption below
// follow the same naming convention but are NOT confirmed by the docs — verify the
// exact export names and prop shapes against @jinx-ui/react before shipping.

import { useCallback, useState } from 'react';
import {
  JxBadge,
  JxCard,
  JxDivider,
  JxOption,
  JxSelect,
  JxSlider,
  JxSwitch,
  JxTab,
  JxTabList,
  JxTabs,
} from '@jinx-ui/react';

export type ThemeMode = 'light' | 'dark' | 'system';
export type FontFamily = 'system' | 'inter' | 'mono';

export interface AppearanceSettings {
  theme: ThemeMode;
  scale: number;
  dense: boolean;
  fontFamily: FontFamily;
}

export interface AppearanceSettingsProps {
  defaultValue?: Partial<AppearanceSettings>;
  onChange?: (settings: AppearanceSettings) => void;
}

const THEME_LABELS: Record<ThemeMode, string> = {
  light: 'Светлая',
  dark: 'Тёмная',
  system: 'Системная',
};

const FALLBACK: AppearanceSettings = {
  theme: 'system',
  scale: 100,
  dense: false,
  fontFamily: 'system',
};

export default function AppearanceSettingsScreen({
  defaultValue,
  onChange,
}: AppearanceSettingsProps) {
  const [settings, setSettings] = useState<AppearanceSettings>({
    ...FALLBACK,
    ...defaultValue,
  });

  const patch = useCallback(
    (next: Partial<AppearanceSettings>) => {
      setSettings((prev) => {
        const merged = { ...prev, ...next };
        onChange?.(merged);
        return merged;
      });
    },
    [onChange],
  );

  return (
    <JxCard>
      <header
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: 'var(--jx-space-3)',
          marginBottom: 'var(--jx-space-5)',
        }}
      >
        <h2 style={{ margin: 0 }}>Внешний вид</h2>
        <JxBadge>{THEME_LABELS[settings.theme]}</JxBadge>
      </header>

      <section style={{ marginBottom: 'var(--jx-space-5)' }}>
        <label htmlFor="appearance-theme">Тема</label>
        <JxTabs
          id="appearance-theme"
          value={settings.theme}
          onValueChange={(value: string) => patch({ theme: value as ThemeMode })}
        >
          <JxTabList aria-label="Тема оформления">
            <JxTab value="light">{THEME_LABELS.light}</JxTab>
            <JxTab value="dark">{THEME_LABELS.dark}</JxTab>
            <JxTab value="system">{THEME_LABELS.system}</JxTab>
          </JxTabList>
        </JxTabs>
      </section>

      <section style={{ marginBottom: 'var(--jx-space-5)' }}>
        <div
          style={{
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'space-between',
            gap: 'var(--jx-space-3)',
          }}
        >
          <label htmlFor="appearance-scale">Масштаб интерфейса</label>
          <span aria-live="polite">{settings.scale}%</span>
        </div>
        <JxSlider
          id="appearance-scale"
          min={80}
          max={140}
          step={5}
          value={settings.scale}
          onValueChange={(value: number) => patch({ scale: value })}
        />
      </section>

      <section style={{ marginBottom: 'var(--jx-space-5)' }}>
        <JxSwitch
          checked={settings.dense}
          onCheckedChange={(checked: boolean) => patch({ dense: checked })}
        >
          Плотная вёрстка
        </JxSwitch>
      </section>

      <JxDivider />

      <section style={{ marginTop: 'var(--jx-space-5)' }}>
        <h3 style={{ marginTop: 0, marginBottom: 'var(--jx-space-3)' }}>Ещё</h3>
        <label htmlFor="appearance-font">Шрифт</label>
        <JxSelect
          id="appearance-font"
          value={settings.fontFamily}
          onValueChange={(value: string) =>
            patch({ fontFamily: value as FontFamily })
          }
        >
          <JxOption value="system">Системный</JxOption>
          <JxOption value="inter">Inter</JxOption>
          <JxOption value="mono">Моноширинный</JxOption>
        </JxSelect>
      </section>
    </JxCard>
  );
}

